local M = class("CastingSwordTaskView",LikeOO.OOPopBase)

M.m_uiName = "CastingSwordMeeting/CastingSwordTask"  -- prefab name
M.m_size_type = 2
M.m_iphoneXAdapter = true

local JianInfo = {
    {animName = "CastingSwordTask_jian01-02", eftName = "eft1", jianName = "jian_01"},
    {animName = "CastingSwordTask_jian01-02", eftName = "eft2", jianName = "jian_02"},
    {animName = "CastingSwordTask_jian02-03", eftName = "eft3", jianName = "jian_03"},
    {animName = "CastingSwordTask_jian03-04", eftName = "eft4", jianName = "jian_04"},
}

function M:onEnter()
    EventDispatcher:registerEvent(GlobalConfig.EVENT_KEYS.EVERY_DAY_EVENT, {self, self.everyDayRefreshEvent})
    EventDispatcher:registerEvent(GlobalConfig.EVENT_KEYS.CLOSE_VIEW, {self, self.colseViewEvent})
    self.jianInfo = JianInfo
    self:bindUI()
    self:refreshUI()
    self:refreshJianEft()
    self:setBgScale()
end

function M:setBgScale()
    local screen_width = U3DUtil:Screen_Width()
    if screen_width >= 1920 then
        local bgObj = self:findGameObject("bg_spine")
        local rect = bgObj:GetComponent("RectTransform")
        rect.localScale = Vector3(1.12,1.12,1.12);
    end
end

function M:refreshUI()
    self:refreshTopNode()
    self:refreshBottomNode()
    self:refreshMiddleNode()
end

function M:bindUI()
    self:initBottomAwards()
    self:setTextByLanKey("close_title_text", "castingSword_str_0038")
    self:setTextByLanKey("text_title", "castingSword_str_0001")
    self:setTextByLanKey("text_previewTitle", "castingSword_str_0006")
    self:setTextByLanKey("today_gift_title", "castingSword_str_0002")
    self:setTextByLanKey("celebrate_title", "castingSword_str_0003")
    self.m_new_box_reward_slider = self:findSlider("progress_slider")
    -- 终极奖励
    self:createMaxAwardList()
end

function M:initBottomAwards()
    local awardDatas = self.m_model.m_allAwardsData
    for i = 1, 4 do
        local boxItem = self:findGameObject("got_btn"..i)
        local transform = boxItem.transform
        local function btns(trans,params)
            self:updateMsg("box_click"..i, {click_transform = trans})
        end
        UIUtil.setButtonClick(transform, btns, i)
        local itemData = awardDatas[i] or {}
        local xlsxData = itemData.xlsxData
        local score = xlsxData.score ~= nil and xlsxData.score or 0
        self:setText("awardCount"..i, score)
    end
end

function M:createMaxAwardList()
    local data = self.m_model.m_allAwardsData[4] or {}
    local xlsxData = data.xlsxData
    local cell_obj = self:findGameObject("awardPreviewNode")
    local transform = cell_obj.transform
    local allAwardData =  xlsxData.reward or {}
    -- 奖励
    for i = 1, 2 do
        local awardData = allAwardData[i]
        local reward_node = UIUtil.findRectTransform(transform, "maxAwardNode"..i)
        UIUtil.destroyAllChild(reward_node)
        if awardData then
            local itemNode = GameUtil:createItemElement(awardData, true, true)
            itemNode.transform:SetParent(reward_node.transform, false)
        end
    end
end

function M:refreshTopNode()
    self:refreshActivityTimer()
end

function M:refreshBottomNode()
    -- 进度条，铸剑总数，当前我的玄铁数
    local itemData = self.m_model.m_allAwardsData[4]
    local maxAwardData = itemData.xlsxData or {}
    local curSlider = self:findSlider("progress_slider")
    curSlider.value = self.m_model.m_score / maxAwardData.score
    self:setText("text_count", self.m_model.m_score)                    
    self:setTextByLanKey("text_hint", "castingSword_str_0013",self.m_model.m_self_score)
    self:refreshAwardNode()
end

function M:refreshAwardNode()
    local awardDatas = self.m_model.m_allAwardsData
    for i = 1, 4 do
        local itemData = awardDatas[i]
        local xlsxData = itemData.xlsxData
        local score = xlsxData.score ~= nil and xlsxData.score or 0
        local isCanGot = (self.m_model.m_score >= score) and (self.m_model.m_score_done[i] == nil)
        self:setObjectVisible("canGotAward_btn"..i, isCanGot)
        self:setObjectVisible("got_btn"..i, (not isCanGot))
    end
    self:refreshGiftBagSlider(awardDatas)
end

function M:refreshTaskList()
    -- 任务列表
    local data = self.m_model.m_taskData.allTaskData
    if self.m_taskScroll_view == nil then
        local loopscroll = self:findGameObject("task_loopscroll")
        local params = {
            show_data = data,
            loop_scroll_object = loopscroll,
            update_cell = function(index, cell_obj, cell_data)
                self:refreshTaskItem(cell_obj, cell_data,false)
            end,
            click_func = function(index, cell_object, cell_data, click_object, click_name)
                audio:SendEvtUI("Play_UI_NormalClick")
                if click_name == "btn_goBtn" then
                    local xlsxData = cell_data.xlsxData
                    local jumpId = xlsxData.go_type
                    QuickOpenFuncUtil:openFunc(jumpId)
                    if (jumpId == 1) or (jumpId == 31) then
                        -- 前往主页, 前往挂机奖励
                        static_rootControl:closeAllViewPop()
                    else
                        self.m_control:closeView()
                    end
                elseif click_name == "btn_getBtn" then
                    local params = {vsn = self.m_model.m_version, quest_id = cell_data.id}
                    self.m_model:getNetData("sword_recv_quest_reward", params, function(response)
                        if response then
                            if self.m_control:activityOverExamine(response) then
                                return
                            end
                            local tempAwardIndex = clone(self.m_model.m_curAwardIndex)
                            RewardUtil:rewardTipsByData(response.reward)
                            cell_data.serverData.status = 2
                            self.m_model:amendTaskData(cell_data.id)
                            local luaBehaviour = UIUtil.findLuaBehaviour(cell_object)
                            self:refreshTaskBtns(luaBehaviour, cell_data.serverData.status)
                            self.m_model:refreshActivityData(response)
                            self:refreshUI()
                            if tempAwardIndex ~= self.m_model.m_curAwardIndex then
                                self:refreshJianEft()
                            end
                        end
                    end, nil, nil, nil)
                elseif click_name == "jifen_obj" then
                    -- 点击积分弹出
                    GameUtil:lookInfoTips(self.m_control, {click_transform = click_object.transform, msg = Language:getTextByKey("castingSword_str_0046")})
                end
            end
        }
        self.m_taskScroll_view = LoopScrollViewUtil.new(params)
    else
        self.m_taskScroll_view:reloadData(data, true)
    end
end

function M:refreshGiftBagSlider(awardDatas)
    local max_index = 0
    local max_num = 0
    local box_num = #awardDatas
    local cur_num = self.m_model.m_score
    for index, awardItemData in ipairs(awardDatas) do
        local itemXlsxData = awardItemData.xlsxData
        max_num = itemXlsxData.score
        max_index = index
        if max_num >= cur_num then
            break
        end
    end
    max_num = max_num > 0 and max_num or 99999
    local start_mun_data = awardDatas[max_index-1]
    local start_mun = start_mun_data and start_mun_data.xlsxData.score or 0
    self.m_new_box_reward_slider.value = math.max(0, (max_index - 1))/box_num + (cur_num - start_mun)/(max_num - start_mun)/box_num
    self:setObjectVisible("openTip", false)--self.m_new_box_reward_slider.value >= 1)
end

function M:refreshTaskBtns(luaBehaviour, status)
    if luaBehaviour then
        LuaBehaviourUtil.setObjectVisible(luaBehaviour, "btn_goBtn", status == 0)
        LuaBehaviourUtil.setObjectVisible(luaBehaviour, "btn_gotBtn", status == 2)
        LuaBehaviourUtil.setObjectVisible(luaBehaviour, "btn_getBtn", status == 1)
    end
end

function M:refreshTaskItem(cell_obj, cell_data, isCurDayTask)
    local luaBehaviour = UIUtil.findLuaBehaviour(cell_obj)
    if luaBehaviour then
        local xlsxData = cell_data.xlsxData
        local serverData = cell_data.serverData
        if not serverData then
            return
        end
        local curValue = (serverData.value ~= nil) and serverData.value or 0
        LuaBehaviourUtil.setTextByLanKey(luaBehaviour, "text_taskTitle", xlsxData.name)
        LuaBehaviourUtil.setTextByLanKey(luaBehaviour, "text_goBtnText","castingSword_str_0004")
        LuaBehaviourUtil.setTextByLanKey(luaBehaviour, "text_gotBtnText","castingSword_str_0005")
        LuaBehaviourUtil.setTextByLanKey(luaBehaviour, "text_getBtnText","castingSword_str_0014")
        self:refreshTaskBtns(luaBehaviour, serverData.status)
        -- 道具玄铁
        local isExistProp = xlsxData.score and (xlsxData.score > 0)
        if isCurDayTask then
            LuaBehaviourUtil.setObjectVisible(luaBehaviour, "my_jifen_obj", isExistProp)
        else
            LuaBehaviourUtil.setObjectVisible(luaBehaviour, "jifen_obj", isExistProp)
        end
        local awardPoint = luaBehaviour:FindGameObject("awardPoint")
        local posX = isExistProp and (60.9) or (-0.9)
        if isCurDayTask then
            posX = isExistProp and (-3.4) or (-65.4)
        end
        UIUtil.setLocalPosition(awardPoint.transform, posX)
        local transform = awardPoint.transform
        if isExistProp then
            LuaBehaviourUtil.setTextByLanKey(luaBehaviour, "reward_num_text",xlsxData.score)
        end
        -- 奖励
        for i = 1, 3 do
            local awardData = xlsxData.reward or {}
            local reward_node = UIUtil.findRectTransform(transform, "awardNode"..i)
            UIUtil.destroyAllChild(reward_node)
            if awardData[i] then
                local itemNode = GameUtil:createItemElement(awardData[i], true, true)
                itemNode.transform:SetParent(reward_node.transform, false)
            end
        end
    end
end

function M:refreshMiddleNode()
    self:refreshTaskList()
    self:refreshCurDayItem()
end

function M:colseViewEvent(event, data)
    if data and data.name ~= "CastingSwordMeeting.CastingSwordTaskInfo" then
        return
    end
    self:everyDayRefreshEvent()
end

function M:everyDayRefreshEvent()
    self.m_model:getNetData("sword_quest_index", {openType = 2}, function(response)
        if response then
            if response["end"] == 1 then
                GameUtil:lookInfoTips(self, {msg = Language:getTextByKey("gf_str_0085"), delay_close = 2})
                self.m_control:closeView()
                return
            end
            self.m_model:refreshActivityData(response)
            self:refreshMiddleNode()
            self:refreshBottomNode()
        end
    end, nil, nil, nil)
end

function M:refreshCurDayItem()
    local myTaskItem = self:findGameObject("myTaskItem")
    local curDayIndex = self.m_model:getActityOpenDay()
    curDayIndex = math.floor(curDayIndex)
    curDayIndex = curDayIndex <= 0 and 1 or curDayIndex
    local itemData = self.m_model.m_taskData.dayTaskData[curDayIndex] or {}
    self:refreshTaskItem(myTaskItem, itemData, true)
end

function M:refreshActivityTimer()
    local startTimer = self.m_model.m_activityData.start_ts
    local endTimer = self.m_model.m_activityData.end_ts
    local starT = TimeUtil.gmTime(startTimer)
    local endT = TimeUtil.gmTime(endTimer)
    local timerFormat = Language:getTextByKey("castingSword_str_0012", starT.year, starT.month, starT.day,
            endT.year, endT.month, endT.day)
    self:setTextByLanKey("text_timer", "castingSword_str_0011",timerFormat)
end

